def _parse_angles(s: str) -> List[float]:
    """Accepts comma or whitespace separated angles."""
    if s is None:
        return []
    s = s.strip()
    if not s:
        return []
    parts = re.split(r"[,\s]+", s)
    return [float(p) for p in parts if p != ""]


def _parse_int_list(values: Sequence[str] | str | int | None) -> List[int]:
    """Accept comma and/or whitespace separated integer lists."""
    if values is None:
        return []
    if isinstance(values, int):
        return [int(values)]
    raw_values = [values] if isinstance(values, str) else [str(v) for v in values]
    parts: List[str] = []
    for raw in raw_values:
        raw = str(raw).strip()
        if not raw:
            continue
        parts.extend([p for p in re.split(r"[,\s]+", raw) if p])
    return [int(p) for p in parts]


def _parse_token_list(values: Sequence[str] | str | None) -> List[str]:
    """Accept comma and/or whitespace separated string tokens."""
    if values is None:
        return []
    raw_values = [values] if isinstance(values, str) else [str(v) for v in values]
    parts: List[str] = []
    for raw in raw_values:
        raw = str(raw).strip()
        if not raw:
            continue
        parts.extend([p for p in re.split(r"[,\s]+", raw) if p])
    return parts


SAVE_OPTION_TOKENS: Tuple[str, ...] = (
    'images',
    'labels',
    'binary',
    'low_quality',
    'nrrd',
    'voxel_volume',
    'high_quality',
    'summary',
)


def resolve_save_options(values: Sequence[str] | str | None) -> List[str]:
    """Validate and canonicalize the unified ``--save`` output selection."""
    valid = set(SAVE_OPTION_TOKENS)
    resolved: List[str] = []
    for raw in _parse_token_list(values):
        token = str(raw).strip().lower()
        if token not in valid:
            expected = ', '.join(SAVE_OPTION_TOKENS)
            raise ValueError(
                f'--save values must be one or more of: {expected}; got {raw!r}'
            )
        if token not in resolved:
            resolved.append(token)
    return resolved


CARTESIAN_VIEW_TOKENS: Tuple[str, ...] = ('transverse', 'sagittal', 'coronal')
RADIAL_VIEW_TOKENS: Tuple[str, ...] = (
    'transverse', 'sagittal', 'coronal',
    'tilted_transverse', 'tilted_sagittal', 'tilted_coronal',
)


def _parse_float_list(values: Sequence[str] | str | float | int | None) -> List[float]:
    """Accept comma and/or whitespace separated floating-point lists."""
    if values is None:
        return []
    if isinstance(values, (float, int)):
        return [float(values)]
    raw_values = [values] if isinstance(values, str) else [str(v) for v in values]
    parts: List[str] = []
    for raw in raw_values:
        raw = str(raw).strip()
        if not raw:
            continue
        parts.extend([p for p in re.split(r"[,\s]+", raw) if p])
    return [float(p) for p in parts]


def _resolve_unique_view_tokens(
    values: Sequence[str] | str | None,
    *,
    valid: Sequence[str],
    flag_name: str,
) -> List[str]:
    raw = [str(v).strip().lower() for v in _parse_token_list(values)]
    valid_set = set(str(v) for v in valid)
    out: List[str] = []
    for token in raw:
        if token not in valid_set:
            expected = ', '.join(str(v) for v in valid)
            raise ValueError(f'{flag_name} values must be one of: {expected}; got {token!r}')
        if token in out:
            raise ValueError(f'{flag_name} contains duplicate value {token!r}')
        out.append(token)
    return out


def resolve_cartesian_views(values: Sequence[str] | str | None) -> List[str]:
    """Resolve ``--enable_cartesian`` without adding any implicit view."""
    return _resolve_unique_view_tokens(
        values,
        valid=CARTESIAN_VIEW_TOKENS,
        flag_name='--enable_cartesian',
    )


def resolve_tilt_angles(values: Sequence[str] | str | None) -> List[float]:
    raw = _parse_float_list(values)
    out: List[float] = []
    seen: set[float] = set()
    for angle in raw:
        angle_f = float(angle)
        if angle_f == 0.0:
            continue
        if angle_f < 0.0:
            raise ValueError('--tilt_angle values must be positive; each non-zero value creates both signed tilt variants')
        if angle_f in seen:
            continue
        seen.add(angle_f)
        out.append(angle_f)
    return out


def resolve_tilt_directions(values: Sequence[str] | str | None) -> List[str]:
    raw = [str(v).strip().lower() for v in _parse_token_list(values)]
    out: List[str] = []
    for token in raw:
        if token == 'both':
            for expanded in ('vertical', 'horizontal'):
                if expanded not in out:
                    out.append(expanded)
            continue
        if token not in ('vertical', 'horizontal'):
            raise ValueError('--tilt_direction values must be vertical, horizontal, or both')
        if token not in out:
            out.append(token)
    # default: both directions whenever Tilted views are enabled.
    if not out:
        out = ['vertical', 'horizontal']
    return out


def resolve_tilt_views(values: Sequence[str] | str | None) -> List[str]:
    """Resolve ``--enable_tilted`` without adding any implicit Tilted base view."""
    return _resolve_unique_view_tokens(
        values,
        valid=CARTESIAN_VIEW_TOKENS,
        flag_name='--enable_tilted',
    )


def resolve_radial_views(values: Sequence[str] | str | None) -> List[str]:
    """Resolve the ordered ``--enable_radial`` transform targets."""
    return _resolve_unique_view_tokens(
        values,
        valid=RADIAL_VIEW_TOKENS,
        flag_name='--enable_radial',
    )


@dataclass(frozen=True)
class ChannelFormat:
    """Canonical model-input channel layout for one center slice."""

    token: str
    kind: str  # gray, rgb, custom
    channel_count: int
    stride: int
    offsets: Tuple[int, ...]


DEFAULT_CHANNEL_FORMAT = ChannelFormat(
    token='gray',
    kind='gray',
    channel_count=1,
    stride=1,
    offsets=(0,),
)

_CUSTOM_CHANNEL_FORMAT_RE = re.compile(r'^C([1-9]\d*)S([1-9]\d*)$', re.IGNORECASE)


def resolve_channel_format(value: str | ChannelFormat | None) -> ChannelFormat:
    """Validate and canonicalize the single ``--channel_format`` value."""
    if isinstance(value, ChannelFormat):
        return value
    raw = 'gray' if value is None else str(value).strip()
    lowered = raw.lower()
    if lowered in {'gray', 'grey'}:
        return DEFAULT_CHANNEL_FORMAT
    if lowered == 'rgb':
        return ChannelFormat('RGB', 'rgb', 3, 1, (0, 0, 0))

    match = _CUSTOM_CHANNEL_FORMAT_RE.fullmatch(raw)
    if match is None:
        raise ValueError(
            f'Unsupported --channel_format value {raw!r}; use gray/grey, RGB, '
            'or C{odd_channel_count}S{stride>=1}, e.g. C5S1'
        )
    channel_count = int(match.group(1))
    stride = int(match.group(2))
    if channel_count % 2 == 0:
        raise ValueError(
            f'--channel_format {raw!r} is invalid: C must be odd, got C={channel_count}'
        )
    if stride < 1:  # Defensive; the regex already excludes zero and negative values.
        raise ValueError(
            f'--channel_format {raw!r} is invalid: S must be an integer >= 1, got S={stride}'
        )
    half = channel_count // 2
    offsets = tuple(position * stride for position in range(-half, half + 1))
    return ChannelFormat(
        token=f'C{channel_count}S{stride}',
        kind='custom',
        channel_count=channel_count,
        stride=stride,
        offsets=offsets,
    )


# Keep this alias table aligned with current Ultralytics configuration semantics.
QUANTIZE_ALIASES: Dict[str, int | str] = {
    '8': 8,
    '16': 16,
    '32': 32,
    'int8': 8,
    'fp16': 16,
    'fp32': 32,
    'w8a8': 8,
    'w16a16': 16,
    'w32a32': 32,
    'w8a16': 'w8a16',
    'w8a32': 'w8a32',
}


def resolve_quantize(value: object) -> int | str | None:
    """Canonicalize the unified Ultralytics inference-precision setting."""
    if value is None:
        return None
    token = str(value).strip().lower()
    if token in {'', 'none', 'null', 'default'}:
        return None
    resolved = QUANTIZE_ALIASES.get(token)
    if resolved is None:
        valid = ', '.join(repr(v) for v in QUANTIZE_ALIASES)
        raise ValueError(f'unsupported --quantize value {value!r}; expected one of {valid}, or none')
    return resolved


def _parse_quantize_arg(value: str) -> int | str | None:
    try:
        return resolve_quantize(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from exc


def quantize_uses_fp16(value: object) -> bool:
    """True only for the FP16 inference scheme; exported INT8 backends own their binding dtype."""
    return resolve_quantize(value) == 16


def quantize_display(value: object) -> str:
    resolved = resolve_quantize(value)
    return 'default/fp32' if resolved is None else str(resolved)


def build_argparser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        description="YOLO segmentation TTA for large cylindrical video volumes.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )

    p.add_argument("--input", required=True, type=str, help="Input video path")
    p.add_argument("--output", default=None, type=str, help="Output directory (default ./{Filename}/)")
    p.add_argument(
        "--temp",
        default=None,
        type=str,
        help=(
            "Scratch/temp root location. The supplied root is created when needed and receives a "
            "unique {Filename}_{PID}_temp run directory. Omission defaults to <output>/temp; "
            "YOLO_TTA_SCRATCH_DIR and an explicit YOLO_TTA_SCRATCH_PREFER_SHM setting remain "
            "compatibility overrides"
        ),
    )
    p.add_argument("--device", nargs="+", default=["0"], type=str,
                   help="Inference device(s). Accepts a single GPU index (0), multiple GPU indices separated by "
                        "commas or spaces (0,1,2,3 or 0 1 2 3) for process-per-GPU scheduling, or cpu. GPU indices and "
                        "cpu cannot be mixed. Indices are torch LOGICAL indices: when SLURM (or the shell) "
                        "exports CUDA_VISIBLE_DEVICES, index N means the (N+1)-th device of that list, not the "
                        "physical GPU id — e.g. under CUDA_VISIBLE_DEVICES=2,3 use --device 0,1 to run on "
                        "physical GPUs 2 and 3")
    p.add_argument("--retina_mask_processor", default=None, choices=["cpu", "gpu"], type=str,
                   help="Device that resolves full-resolution retina masks. CUDA defaults to gpu for "
                        "all CUDA runs; an explicit cpu/gpu value is honored. --device cpu "
                        "forces cpu and overrides any explicit value")
    p.add_argument("--model", required=True, type=str, help="Path to a single YOLO segmentation model")
    p.add_argument(
        "--channel_format",
        default="gray",
        type=str,
        metavar="{gray,RGB,CxSy}",
        help=(
            "Model-input channel layout. gray/grey uses center slice N as one channel; "
            "RGB triplicates N into three channels; C{odd}S{stride>=1}, e.g. C5S1, "
            "uses edge-clamped neighboring view slices in ascending offset order. "
            "Only one value is accepted and every prediction remains assigned to N"
        ),
    )

    p.add_argument("--imgsz", default=2048, type=int, help="Square input size used for YOLO predict")
    p.add_argument("--batch", default=1, type=int, help="Batch size passed to YOLO predict. The in-memory source pads the final batch by repeating the last real slice and discards synthetic results, which supports fixed-batch engines such as TensorRT builds without dynamic=True")
    p.add_argument("--conf", default=0.15, type=float, help="Passed to YOLO predict")
    p.add_argument("--min_conf", default=0.30, type=float,
                   help="Remove prediction-set objects whose combined confidence is below this threshold. 0 disables the check")
    p.add_argument(
        "--quantize",
        default=None,
        type=_parse_quantize_arg,
        metavar="{8,int8,w8a8,16,fp16,w16a16,32,fp32,w32a32,w8a16,w8a32}",
        help=(
            "Unified Ultralytics precision setting. 16/fp16/w16a16 requests FP16; "
            "32/fp32/w32a32 or omission uses FP32. 8/int8/w8a8 and mixed schemes describe "
            "exported quantized backends; quantization/calibration occurs during export"
        ),
    )

    p.add_argument("--angle", default="0,120,240", type=str,
                   help="Rotation angles in degrees for augmentation (comma or whitespace separated)")
    p.add_argument("--min_radius", default=0.0, type=float,
                   help="Remove objects whose radius is smaller than this value, measured on the YOLO output masks "
                        "in each prediction set's own native 2D slice plane, before backprojection, independently "
                        "per active view. 0 disables the check")
    p.add_argument("--keep_objects", default=0, type=int,
                   help="Keep the top N largest final 3D objects by volume. 0 keeps all objects")

    p.add_argument(
        "--enable_cartesian",
        nargs="+",
        default=None,
        type=str,
        metavar="VIEW",
        help=(
            "Enable one or more Cartesian views: transverse, sagittal, coronal. "
            "Comma-separated, whitespace-separated, and mixed comma/whitespace forms are accepted. "
            "No Cartesian view is enabled by default"
        ),
    )
    p.add_argument(
        "--enable_radial",
        nargs="+",
        default=None,
        type=str,
        metavar="VIEW",
        help=(
            "Enable one or more Radial transforms: transverse, sagittal, coronal, "
            "tilted_transverse, tilted_sagittal, tilted_coronal. Cartesian Radial transforms "
            "do not require the matching upright Cartesian view. A tilted_* target expands to "
            "every enabled Tilted variant of that base; it is skipped with a log message when none exist"
        ),
    )
    p.add_argument(
        "--azimuth_angle",
        nargs="+",
        default=None,
        type=str,
        metavar="DEG",
        help=(
            "Radial angular spacing over [0,180). One value broadcasts to every --enable_radial "
            "target; multiple values must match the ordered --enable_radial target count. Omission "
            "uses the largest full-coverage angle independently for each target. Supplying this flag "
            "alone does not enable Radial views; 0 disables its paired target"
        ),
    )
    p.add_argument(
        "--enable_tilted",
        nargs="+",
        default=None,
        type=str,
        metavar="VIEW",
        help=(
            "Enable one or more Tilted Cartesian bases: transverse, sagittal, coronal. "
            "No Tilted view is enabled by default, and the base need not be enabled by --enable_cartesian"
        ),
    )
    p.add_argument("--tilt_angle", nargs="+", default=["30"], type=str,
                   help="One or more positive Tilted View angles in degrees. Each value creates both positive and negative variants. 0 disables all Tilted views even when --enable_tilted is set. Values must be greater than 0 and less than or equal to 45")
    p.add_argument("--tilt_direction", nargs="+", default=["vertical", "horizontal"], type=str,
                   help="One or more Tilted View directions: vertical, horizontal, or both. Defaults to vertical and horizontal")

    p.add_argument("--tile_size", nargs="+", default=["0"], type=str,
                   help="One or more square dense-tile side lengths in source pixels for all active views. 0 disables dense tiled predictions")
    p.add_argument("--tile_stride", nargs="+", default=["0"], type=str,
                   help="One or more dense-tile strides in source pixels. Values are index-paired with --tile_size; one stride broadcasts to every tile size. Each stride must be <= its paired tile size")

    p.add_argument(
        "--save",
        nargs="+",
        default=None,
        type=str,
        metavar="OUTPUT",
        help=(
            "Save one or more output groups: images (active-view PNG sequences), labels "
            "(final YOLO segmentation labels), binary (final TIFF sequence plus FFV1 MKV), "
            "low_quality (isotropically downsampled overlay and binary videos), nrrd "
            "(single-layer Slicer decomposition plus manifest), voxel_volume (native-space "
            "white-voxel count for the summary), high_quality (native-resolution final overlay), "
            "and summary (summary text file). Comma-separated, whitespace-separated, and mixed "
            "forms are accepted. No output group is selected by default; existing output paths "
            "and filenames are retained"
        ),
    )
    p.add_argument(
        "--low_quality_downbin",
        nargs="+",
        default=None,
        type=str,
        help=(
            "One or more isotropic low-quality downbins. Floats scale each X/Y/t dimension, "
            "e.g. 0.5. Integers scale the largest dimension to that value. Providing this flag "
            "retains the prior behavior and implies --save low_quality"
        ),
    )
    p.add_argument("--enable_3d_void_fill", action="store_true",
                   help="Apply one final 3D enclosed-void fill after the global union. Disabled by default")
    p.add_argument("--centerline_filter_passes", default=0, type=int,
                   help="Maximum centerline-guided post-union passes. Pass 0 is the untouched audit checkpoint; 0 disables filtering and its audit NRRDs")
    p.add_argument("--centerline_filter_backend", default="embedded", choices=["embedded", "off"],
                   help="Centerline backend. embedded uses the in-script SciPy EDT medial-ridge tracker; off disables filtering")
    p.add_argument("--centerline_auto_remove", action="store_true",
                   help="Opt in to removing whole unprotected 2D components that satisfy every centerline, temporal, and backend-reliability guard. Protected connected anatomy remains marker-only; this flag never subtracts a watershed partition")
    p.add_argument("--centerline_radius_factor", default=2.5, type=float, metavar="X",
                   help="Flag foreground that reaches the circle of radius X times the local EDT medial-ridge radius in the strict tangent-normal 2D plane")
    p.add_argument("--centerline_temporal_context", default=8, type=int,
                   help="Clean source slices required on each side before an unprotected 2D component may be removed. Centerline anomaly runs themselves have no duration cap")
    p.add_argument("--centerline_surface_max_dim", default=512, type=int,
                   help="Maximum axis of the block-max-pooled foreground crop supplied to the centerline backend; bounds extraction without striding away thin branches")
    p.add_argument("--centerline_surface_points", default=5000, type=int,
                   help="Centerline complexity budget. The embedded backend permits up to approximately 4x this many raw ridge samples before its global safety cap")
    p.add_argument("--centerline_timeout", default=900.0, type=float,
                   help="Seconds allowed for each isolated embedded-centerline attempt before preserving the current union and using safe pass-through behavior")
    p.add_argument("--gaussian_smoothing", nargs="?", const=3.0, default=None, type=float, metavar="SIGMA",
                   help="Final 3D Gaussian smoothing sigma in voxel units. Unset uses default 3.0 when smoothing is activated by either Gaussian flag; explicitly set 0 to disable")
    p.add_argument("--gaussian_smoothing_passes", default=None, type=int,
                   help="Number of Gaussian smoothing passes. Unset uses default 1 when smoothing is activated by either Gaussian flag; explicitly set 0 to disable")

    p.add_argument("--troubleshooting", action="store_true",
                   help="Save FFV1 MKV troubleshooting overlays for each active full-frame view and consolidated tiled prediction set")
    p.add_argument("--interpolate", default=15, type=int,
                   help="Maximum view-native slice/frame distance used to search for interpolation candidates. Radial interpolation wraps around frame order. 0 disables interpolation")
    p.add_argument("--interpolation_walk_back", default=3, type=int,
                   help="Additional source slices to bridge before the endpoint slice. 0 disables walk-back bridges")
    p.add_argument("--interpolation_candidates", default=1, type=int,
                   help="Accept up to the Nth nearest interpolation candidate per endpoint projection")
    p.add_argument("--interpolate_passes", default=1, type=int,
                   help="Run the interpolation process this many passes, treating the previous pass as real")
    p.add_argument("--interpolate_min_radius", default=3, type=float,
                   help="Reject a candidate connection if the bridge radius is equal to, or smaller than, this value. 0 disables the check")
    p.add_argument("--interpolation_search_angle", default=15.0, type=float,
                   help="Projection growth angle in degrees. Must be greater than -90 and less than 90")

    return p


